html:
{%- set slips = frappe.get_all("Salary Slip", filters={"payroll_entry": doc.name, "docstatus": ["!=", 2]}, fields=["name"], order_by="employee asc") -%}
{%- set ns = namespace(gross=0, ded=0, net=0) -%}

<style>
	@page { size: A4 landscape; margin: 10mm; }
	.payroll-wrapper { font-family: Arial, sans-serif; font-size: 11px; color: #1a1a1a; }
	.payroll-title { text-align: center; margin: 6px 0 10px 0; font-size: 16px; font-weight: bold; color: #1f3864; letter-spacing: 0.5px; }
	.payroll-company { text-align: center; font-size: 14px; font-weight: bold; }
	table.payroll-table { width: 100%; border-collapse: collapse; table-layout: fixed; }
	table.payroll-table th { background: #1f3864; color: #fff; padding: 6px 5px; border: 1px solid #1f3864; text-align: center; font-size: 11px; }
	table.payroll-table td { padding: 5px; border: 1px solid #b8c4d6; vertical-align: top; word-wrap: break-word; }
	table.payroll-table tbody tr:nth-child(odd) td { background: #eaf1fb; }
	table.payroll-table tbody tr:nth-child(even) td { background: #ffffff; }
	.num { text-align: right; white-space: nowrap; }
	.strong { font-weight: bold; }
	.comp-line { line-height: 1.5; }
	table.payroll-table tr.grand td { background: #1f3864 !important; color: #fff; font-weight: bold; border-color: #1f3864; }
</style>

<div class="payroll-wrapper">
	{% if letter_head and not no_letterhead %}
		<div class="letter-head">{{ letter_head }}</div>
	{% endif %}
	{% if not letter_head or no_letterhead %}<div class="payroll-company">{{ doc.company }}</div>{% endif %}
	<div class="payroll-title">{{ frappe.utils.formatdate(doc.start_date, "MMMM yyyy")|upper }} - PAYROLL SUMMARY</div>

	<table class="payroll-table">
		<colgroup>
			<col style="width: 12%"><col style="width: 14%"><col style="width: 19%"><col style="width: 11%">
			<col style="width: 19%"><col style="width: 12%"><col style="width: 13%">
		</colgroup>
		<thead>
			<tr>
				<th>Employee ID</th>
				<th>Employee Name</th>
				<th>Earnings</th>
				<th>Earnings Total</th>
				<th>Deductions</th>
				<th>Deductions Total</th>
				<th>Net Total</th>
			</tr>
		</thead>
		<tbody>
			{% for row in slips %}
				{%- set slip = frappe.get_doc("Salary Slip", row.name) -%}
				{%- set ns.gross = ns.gross + (slip.gross_pay or 0) -%}
				{%- set ns.ded = ns.ded + (slip.total_deduction or 0) -%}
				{%- set ns.net = ns.net + (slip.net_pay or 0) -%}
				<tr>
					<td>{{ slip.employee }}</td>
					<td>{{ slip.employee_name }}</td>
					<td>
						{% for e in slip.earnings %}
							<div class="comp-line">{{ e.salary_component }}: {{ "{:,.2f}".format(e.amount or 0) }}</div>
						{% endfor %}
					</td>
					<td class="num strong">{{ "{:,.2f}".format(slip.gross_pay or 0) }}</td>
					<td>
						{% for d in slip.deductions %}
							<div class="comp-line">{{ d.salary_component }}: {{ "{:,.2f}".format(d.amount or 0) }}</div>
						{% endfor %}
					</td>
					<td class="num strong">{{ "{:,.2f}".format(slip.total_deduction or 0) }}</td>
					<td class="num strong">{{ "{:,.2f}".format(slip.net_pay or 0) }}</td>
				</tr>
			{% endfor %}
			<tr class="grand">
				<td colspan="3" class="num">GRAND TOTAL</td>
				<td class="num">{{ "{:,.2f}".format(ns.gross) }}</td>
				<td></td>
				<td class="num">{{ "{:,.2f}".format(ns.ded) }}</td>
				<td class="num">{{ "{:,.2f}".format(ns.net) }}</td>
			</tr>
		</tbody>
	</table>
</div>
